# Check if 2s form complete rectangles
# Get bounding box for each connected group of 2s
def find_2_groups():
    visited = set()
    groups = []
    for r in range(25):
        for c in range(19):
            if demo_output[r][c] == 2 and (r, c) not in visited:
                group = []
                # BFS for 8-connectivity
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    group.append((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < 25 and 0 <= nc < 19 and demo_output[nr][nc] == 2 and (nr, nc) not in visited:
                                stack.append((nr, nc))
                groups.append(group)
    return groups

groups = find_2_groups()
print(f"Number of connected 2-groups: {len(groups)}")

for i, group in enumerate(groups):
    rows = [r for r, c in group]
    cols = [c for r, c in group]
    print(f"Group {i}: H={len(group)}, rows {min(rows)}-{max(rows)}, cols {min(cols)}-{max(cols)}")
